package au.aumanet.app;
import android.content.Context;
import android.graphics.*;
import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Private normalized JPEGs only. Paths are derived from authenticated identifiers,
 * never supplied by the WebView or a remote peer. One message worker owns writes. */
final class GroupImageFiles {
    static final long QUOTA=64L*1024*1024;private static final int[] JPEG_QUALITIES={85,72,58,44};final File directory;
    GroupImageFiles(Context context)throws Exception{directory=new File(context.getNoBackupFilesDir(),"group-images-v2");if(!directory.exists()&&!directory.mkdirs())throw new IOException("Private image storage unavailable");if(!directory.isDirectory())throw new IOException("Private image storage unavailable");}
    private File file(GroupTextStore.Scope scope,String sender,String id,String suffix)throws Exception{return new File(directory,GroupTextWire.hash((scope.key+":"+GroupTextWire.pin(sender)+":"+GroupTextWire.id(id)).getBytes(java.nio.charset.StandardCharsets.US_ASCII))+suffix);}
    boolean room(int bytes){long used=0;File[] files=directory.listFiles();if(files==null)return false;for(File f:files){long size=f.length();if(size<0||size>QUOTA-used)return false;used+=size;}return bytes>=0&&used<=QUOTA-bytes;}
    static final class Prepared{final byte[] bytes;final GroupTextWire.Image image;Prepared(byte[] bytes,GroupTextWire.Image image){this.bytes=bytes;this.image=image;}}
    Prepared normalize(JSONObject input)throws Exception{
        String encoded=GroupTextWire.string(input,"dataBase64"),source=GroupTextWire.string(input,"sha256");long expected=GroupTextWire.integer(input,"byteLength");if(expected<1||expected>GroupTextWire.MAX_IMAGE||encoded.length()>GroupTextWire.MAX_IMAGE_BASE64||!source.matches("[A-F0-9]{64}")||!"image/jpeg".equals(GroupTextWire.string(input,"mimeType")))throw new IllegalArgumentException("Prepared image exceeds its bounds");
        byte[] bytes=Base64.getDecoder().decode(encoded);if(bytes.length!=expected||!GroupTextWire.hash(bytes).equals(source))throw new SecurityException("Prepared image content changed");
        BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);int w=bounds.outWidth,h=bounds.outHeight;if(w<1||h<1||w>GroupTextWire.MAX_IMAGE_EDGE||h>GroupTextWire.MAX_IMAGE_EDGE||!"image/jpeg".equals(bounds.outMimeType)||w!=GroupTextWire.integer(input,"width")||h!=GroupTextWire.integer(input,"height"))throw new IllegalArgumentException("Prepared image dimensions changed");
        Bitmap decoded=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(decoded==null)throw new IllegalArgumentException("Cannot decode image");byte[] normalized=null;try{for(int quality:JPEG_QUALITIES){CappedJpegOutput out=new CappedJpegOutput();if(!decoded.compress(Bitmap.CompressFormat.JPEG,quality,out))throw new IOException("Cannot normalize image");if(!out.overflow&&out.bytes.size()>0){normalized=out.bytes.toByteArray();break;}}}finally{decoded.recycle();}
        if(normalized==null)throw new IllegalArgumentException("Normalized image exceeds 1 MiB; choose a smaller image");return new Prepared(normalized,new GroupTextWire.Image(w,h,normalized.length,GroupTextWire.hash(normalized),source));
    }
    /** Discard overflow while the encoder finishes; retained output never exceeds the wire cap. */
    private static final class CappedJpegOutput extends OutputStream{final ByteArrayOutputStream bytes=new ByteArrayOutputStream(8192);boolean overflow;
        @Override public void write(int value){if(bytes.size()<GroupTextWire.MAX_IMAGE)bytes.write(value);else overflow=true;}
        @Override public void write(byte[] value,int offset,int length){if(value==null)throw new NullPointerException();if(offset<0||length<0||offset>value.length-length)throw new IndexOutOfBoundsException();int accepted=Math.min(length,GroupTextWire.MAX_IMAGE-bytes.size());if(accepted>0)bytes.write(value,offset,accepted);if(accepted<length)overflow=true;}
    }
    void put(GroupTextStore.Scope scope,String sender,String id,byte[] bytes,GroupTextWire.Image image)throws Exception{
        validate(bytes,image);File target=file(scope,sender,id,".jpg"),part=file(scope,sender,id,".part");if(target.exists()){read(scope,sender,id,image);return;}if(!room(bytes.length))throw new IOException("Private image storage is full; clear local history first");write(part,bytes);Files.move(part.toPath(),target.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);syncDirectory();
    }
    byte[] read(GroupTextStore.Scope scope,String sender,String id,GroupTextWire.Image image)throws Exception{byte[] bytes=readBounded(file(scope,sender,id,".jpg"),image.bytes);validate(bytes,image);return bytes;}
    boolean available(GroupTextStore.Scope scope,String sender,String id,GroupTextWire.Image image){try{read(scope,sender,id,image);return true;}catch(Exception e){return false;}}
    int partial(GroupTextStore.Scope scope,String sender,String id,int committed)throws Exception{File f=file(scope,sender,id,".part");if(f.length()<committed)committed=0;if(f.exists()&&f.length()!=committed)try(RandomAccessFile out=new RandomAccessFile(f,"rw")){out.setLength(committed);}return committed;}
    int append(GroupTextStore.Scope scope,String sender,String id,GroupTextWire.Image image,int offset,byte[] chunk,java.util.function.BooleanSupplier live)throws Exception{if(!live.getAsBoolean())throw new IllegalStateException("Image transfer was stopped or expired");if(chunk.length<1||chunk.length>GroupTextWire.CHUNK||offset<0||offset>image.bytes-chunk.length)throw new IllegalArgumentException("Invalid image chunk");File f=file(scope,sender,id,".part");if(f.length()!=offset)throw new IOException("Image transfer offset changed");if(!room(chunk.length))throw new IOException("Private image storage is full");try(RandomAccessFile out=new RandomAccessFile(f,"rw")){out.seek(offset);out.write(chunk);out.getFD().sync();}int next=offset+chunk.length;if(next==image.bytes){if(!live.getAsBoolean())throw new IllegalStateException("Image transfer was stopped or expired");byte[] bytes=readBounded(f,image.bytes);validate(bytes,image);if(!live.getAsBoolean())throw new IllegalStateException("Image transfer was stopped or expired");Files.move(f.toPath(),file(scope,sender,id,".jpg").toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);syncDirectory();}return next;}
    void cancel(GroupTextStore.Scope scope,String sender,String id)throws Exception{Files.deleteIfExists(file(scope,sender,id,".part").toPath());}
    void clear(GroupTextStore.Scope scope,List<JSONObject> removed)throws Exception{for(JSONObject row:removed){String sender=row.getString("senderId"),id=row.getString("id");Files.deleteIfExists(file(scope,sender,id,".jpg").toPath());cancel(scope,sender,id);}}
    static String reference(String scope,String sender,String id)throws Exception{return GroupTextWire.hash((scope+":"+sender+":"+id).getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
    void sweep(Set<String> references)throws Exception{File[] files=directory.listFiles();if(files==null)throw new IOException("Cannot enumerate private image storage");for(File file:files){String name=file.getName();if(!name.matches("[A-F0-9]{64}\\.(jpg|part)"))throw new IOException("Unexpected private image storage entry");if(!references.contains(name.substring(0,64)))Files.deleteIfExists(file.toPath());}syncDirectory();}
    private void syncDirectory()throws Exception{java.io.FileDescriptor directoryFd=android.system.Os.open(directory.getAbsolutePath(),android.system.OsConstants.O_RDONLY,0);try{android.system.Os.fsync(directoryFd);}finally{android.system.Os.close(directoryFd);}}
    private static void write(File target,byte[] bytes)throws Exception{try(FileOutputStream out=new FileOutputStream(target)){out.write(bytes);out.getFD().sync();}}
    private static byte[] readBounded(File file,int expected)throws Exception{if(expected<1||expected>GroupTextWire.MAX_IMAGE||file.length()!=expected)throw new IOException("Image is not available locally");byte[] bytes=new byte[expected];try(FileInputStream in=new FileInputStream(file)){int at=0;while(at<expected){int count=in.read(bytes,at,expected-at);if(count<0)throw new IOException("Image is not available locally");at+=count;}if(in.read()!=-1)throw new IOException("Image is not available locally");}return bytes;}
    private static void validate(byte[] bytes,GroupTextWire.Image image)throws Exception{if(bytes.length!=image.bytes||!GroupTextWire.hash(bytes).equals(image.sha)||bytes.length<4||(bytes[0]&255)!=255||(bytes[1]&255)!=216||(bytes[bytes.length-2]&255)!=255||(bytes[bytes.length-1]&255)!=217)throw new SecurityException("Image integrity verification failed");BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth!=image.width||bounds.outHeight!=image.height||!"image/jpeg".equals(bounds.outMimeType))throw new SecurityException("Image dimensions do not match its signed manifest");}
}
